"use strict";(self.webpackChunkbellplay_docs=self.webpackChunkbellplay_docs||[]).push([[83888],{66740:e=>{e.exports=JSON.parse('{"tag":{"label":"normalize","permalink":"/docs/tags/normalize","allTagsPath":"/docs/tags","count":19,"items":[{"id":"learn/examples/resynthesis","title":"1. Audio resynthesis","description":"A simple demonstration of granular quasi-resynthesis via partial tracks, where an sound is used to guide the behavior of sinusoidal grains.","permalink":"/docs/learn/examples/resynthesis"},{"id":"learn/examples/audiomosaic","title":"10. Audio mosaicing","description":"An example of basic audio mosaicking in bellplay~, where a target audio file is reconstructed using segments drawn from a small audio corpus.","permalink":"/docs/learn/examples/audiomosaic"},{"id":"learn/examples/temporalalignment","title":"11. Envelope-aware temporal alignment","description":"This example demonstrates how to align the envelopes of different audio samples based on their peak amplitude times.","permalink":"/docs/learn/examples/temporalalignment"},{"id":"learn/tutorials/postprocessing","title":"11. Post-rendering processing","description":"Sometimes it can be more useful or desirable to apply processing to the entire output, instead of processing each buffer individually.","permalink":"/docs/learn/tutorials/postprocessing"},{"id":"learn/examples/shepardtone","title":"12. Shepard-Risset glissando","description":"This example synthesizes a Shepard-Risset glissando using bellplay~.","permalink":"/docs/learn/examples/shepardtone"},{"id":"learn/examples/neuralsynth","title":"14. Neural synthesizer","description":"This tutorial demonstrates how to use a multi-layer perceptron (MLP) neural network","permalink":"/docs/learn/examples/neuralsynth"},{"id":"learn/tutorials/analysis","title":"15. Audio descriptors","description":"One of the core features in bellplay~ is our ability to analyze buffers to extract relevant information.","permalink":"/docs/learn/tutorials/analysis"},{"id":"learn/tutorials/analysismodes","title":"16. Audio descriptor modes","description":"When analyzing buffers, we can specify the output format for many of the available audio descriptors.","permalink":"/docs/learn/tutorials/analysismodes"},{"id":"learn/tutorials/features","title":"17. More audio features","description":"This tutorial provides an additional example for using buffer analysis features for audio processing.","permalink":"/docs/learn/tutorials/features"},{"id":"learn/tutorials/multirendering","title":"20. Multi-rendering","description":"This tutorial demonstrates a very simple but consequential feature in bellplay~\u2014namely, the ability to reuse rendered buffers multiple times to further refine and sculpt the final output into complex and intricate sounds.","permalink":"/docs/learn/tutorials/multirendering"},{"id":"learn/tutorials/sampling","title":"21. Basic sampling","description":"In bellplay~, the ezsampler function provides a minimal but flexible interface for mapping symbolic pitch and velocity information to audio buffers.","permalink":"/docs/learn/tutorials/sampling"},{"id":"learn/tutorials/importingmidi","title":"22. Importing MIDI","description":"bellplay~ supports importing MIDI files (.mid or .midi) into our scripts, each described as a list of events.","permalink":"/docs/learn/tutorials/importingmidi"},{"id":"learn/tutorials/scoreconfig","title":"23. Score formatting and appearance","description":"Depending on what you\'re doing, you might want to have more control over what the score transcription looks like.","permalink":"/docs/learn/tutorials/scoreconfig"},{"id":"learn/tutorials/kdtree","title":"24. Feature-driven sampling","description":"This tutorial shows how to build k-dimensional trees to efficiently perform feature-based search on buffers.","permalink":"/docs/learn/tutorials/kdtree"},{"id":"learn/tutorials/sourceseparation","title":"25. Audio source separation","description":"This tutorial demonstrates how to perform rudimentary source separation","permalink":"/docs/learn/tutorials/sourceseparation"},{"id":"learn/examples/feedbacksynth","title":"3. Feedback synthesis","description":"This code demonstrates a feedback-based synthesis technique, where buffers are routed back into their own processing chain to create a rich, evolving drone.","permalink":"/docs/learn/examples/feedbacksynth"},{"id":"learn/examples/syntharpeggio","title":"4. Synth arpeggio","description":"This example demonstrates how to use BPFs to continuously change the pitch of different oscillators.","permalink":"/docs/learn/examples/syntharpeggio"},{"id":"learn/examples/waveshaping","title":"5. Waveshaping buffers","description":"A basic example of waveshaping in bellplay~, using a randomly generated breakpoint function.","permalink":"/docs/learn/examples/waveshaping"},{"id":"learn/examples/gliss","title":"6. Glissando texture","description":"An example of using time-varying resampling to generate a polyphonic texture.","permalink":"/docs/learn/examples/gliss"}],"unlisted":false}}')}}]);